"""Helpers that keep user-supplied names from escaping their intended directories."""
import re
from pathlib import Path

from fastapi import HTTPException

from backend.app.core.config import settings

# Project ids are generated by ProjectService.create_project as proj_<10 hex chars>.
PROJECT_ID_RE = re.compile(r"proj_[0-9a-f]{10}")
# Architecture keys are enum values such as "resnet18", "yolov8n", "dfine_s".
ARCHITECTURE_RE = re.compile(r"[A-Za-z0-9_.-]{1,64}")


def is_valid_project_id(project_id: str) -> bool:
    # fullmatch: unlike re.match + `$`, it does not accept a trailing newline.
    return bool(PROJECT_ID_RE.fullmatch(project_id or ""))


def validate_project_id(project_id: str) -> str:
    if not is_valid_project_id(project_id):
        raise HTTPException(status_code=404, detail=f"Project {project_id} not found")
    return project_id


def validate_architecture(architecture: str) -> str:
    if not ARCHITECTURE_RE.fullmatch(architecture or "") or ".." in architecture:
        raise HTTPException(status_code=400, detail=f"Invalid architecture: {architecture}")
    return architecture


def safe_filename(filename: str) -> str:
    """Reject anything that is not a plain file name (no separators, no dot-dot, no drive)."""
    name = filename or ""
    if (
        not name
        or name in (".", "..")
        or name.startswith(".")
        or "/" in name
        or "\\" in name
        or ":" in name
        or "\x00" in name
        or Path(name).name != name
    ):
        raise HTTPException(status_code=400, detail=f"Invalid file name: {filename}")
    return name


def resolve_project_dir(project_id: str) -> Path:
    """The one place project directories are built: validates the id, so no caller can escape PROJECTS_DIR."""
    return settings.PROJECTS_DIR / validate_project_id(project_id)
